+        cleanup();
+        Files.createDirectory(confPath);
+        Files.copy(
+            tempDir.resolve("elasticsearch.keystore"),
+            confPath.resolve("elasticsearch.keystore"),
+            StandardCopyOption.COPY_ATTRIBUTES
